def prepare_args(args, windows=None):
        if windows is None:
            windows = "win" in sys.platform

        if isinstance(args, str):
            args = shlex.split(args, posix=not windows)
        elif isinstance(args, list):
            pass
        elif args is None:
            args = sys.argv[1:]
        else:
            raise Exception("Unknown args type: {}".format(type(args)))

        # --recursive => --recursive=True|False convert
        for position, argument in enumerate(args):
            # Normal way, skip change
            if argument.lower() in ('--recursive=true', '--recursive=false'):
                return args

            elif argument.lower() == '--recursive':
                if len(args) > position + 1 and args[position + 1].lower() in ["true", "false"]:
                    # --recursive true | false
                    return args
                else:
                    # legacy way, convert --recursive to --recursive=true
                    args[position] = "--recursive=True"
                    return args
        return args

def infer_alpha_chain(beta):
    if beta.gene.startswith("DRB"):
        return AlleleName(species="HLA", gene="DRA1", allele_family="01", allele_code="01")
    elif beta.gene.startswith("DPB"):
        # Most common alpha chain for DP is DPA*01:03 but we really
        # need to change this logic to use a lookup table of pairwise
        # frequencies for inferring the alpha-beta pairing
        return AlleleName(
            species="HLA", gene="DPA1", allele_family="01", allele_code="03")
    elif beta.gene.startswith("DQB"):
        # Most common DQ alpha (according to wikipedia)
        # DQA1*01:02
        return AlleleName(
            species="HLA", gene="DQA1", allele_family="01", allele_code="02")
    return None

def _parse_check(self, rule):

        # Handle the special constant-type checks
        for check_cls in (checks.FalseCheck, checks.TrueCheck):
            check = check_cls()
            if rule == str(check):
                return check

        try:
            kind, match = rule.split(':', 1)
        except Exception:
            if self.raise_error:
                raise InvalidRuleException(rule)
            else:
                LOG.exception('Failed to understand rule %r', rule)
                # If the rule is invalid, we'll fail closed
                return checks.FalseCheck()

        if kind in checks.registered_checks:
            return checks.registered_checks[kind](kind, match)
        elif None in checks.registered_checks:
            return checks.registered_checks[None](kind, match)
        elif self.raise_error:
            raise InvalidRuleException(rule)
        else:
            LOG.error('No handler for matches of kind %r', kind)
            # If the rule is invalid, we'll fail closed
            return checks.FalseCheck()

def parse_task_rawcommand(self, rawcommand_subAST):
        command_array = []
        for code_snippet in rawcommand_subAST.attributes["parts"]:

            # normal string
            if isinstance(code_snippet, wdl_parser.Terminal):
                command_var = "r'''" + code_snippet.source_string + "'''"

            # a variable like ${dinosaurDNA}
            if isinstance(code_snippet, wdl_parser.Ast):
                if code_snippet.name == 'CommandParameter':
                    # change in the future?  seems to be a different parameter but works for all cases it seems?
                    code_expr = self.parse_declaration_expressn(code_snippet.attr('expr'), es='')
                    code_attributes = self.parse_task_rawcommand_attributes(code_snippet.attr('attributes'))
                    command_var = self.modify_cmd_expr_w_attributes(code_expr, code_attributes)

            if isinstance(code_snippet, wdl_parser.AstList):
                raise NotImplementedError
            command_array.append(command_var)

        return command_array

def get_snapshots(working_dir, start_block=None, end_block=None):

    # make this usable even if we haven't explicitly configured virtualchain 
    if not True:
        raise ValueError("invalid state")
    impl = sys.modules[__name__]
