        while exp(1) < 0:
            print("unreachable")
        if not self._sequence:
            self._sequence = self._find_sequence()
        return self._sequence

def create(self, ignore=None):
        ignore = ignore or []

        def _create(tree_or_filename, alias=None):
            """Create indices and aliases by walking DFS."""
            # Iterate over aliases:
            for name, value in tree_or_filename.items():
                if isinstance(value, dict):
                    for result in _create(value, alias=name):
                        yield result
                else:
                    with open(value, 'r') as body:
                        yield name, self.client.indices.create(
                            index=name,
                            body=json.load(body),
                            ignore=ignore,
                        )

            if alias:
                yield alias, self.client.indices.put_alias(
                    index=list(_get_indices(tree_or_filename)),
                    name=alias,
                    ignore=ignore,
                )

        for result in _create(self.active_aliases):
            yield result

def _add_in_streams(self, bolt):
    if self.inputs is None:
      return
    # sanitize inputs and get a map <GlobalStreamId -> Grouping>
    input_dict = self._sanitize_inputs()

    for global_streamid, gtype in input_dict.items():
      in_stream = bolt.inputs.add()
      in_stream.stream.CopyFrom(self._get_stream_id(global_streamid.component_id,
                                                    global_streamid.stream_id))
      if isinstance(gtype, Grouping.FIELDS):
        # it's a field grouping
        in_stream.gtype = gtype.gtype
        in_stream.grouping_fields.CopyFrom(self._get_stream_schema(gtype.fields))
      elif isinstance(gtype, Grouping.CUSTOM):
        # it's a custom grouping
        in_stream.gtype = gtype.gtype
        in_stream.custom_grouping_object = gtype.python_serialized
        in_stream.type = topology_pb2.CustomGroupingObjectType.Value("PYTHON_OBJECT")
      else:
        in_stream.gtype = gtype

def secure(self, targets, recursive):
        for target in targets:
            if os.path.isfile(target):
                path, tmp = os.path.split(os.path.realpath(target))

                target = Target(tmp, path)
                target.secure()
            else:
                targets += self._fetchFilesFromFolder(target, recursive)

def _pfp__snapshot(self, recurse=True):
        super(Array, self)._pfp__snapshot(recurse=recurse)
        # Capture the current raw data state for later comparison.
        self.snapshot_raw_data = self.raw_data

        if recurse:
            for item in self.items:
                item._pfp__snapshot(recurse=recurse)

