def fmt_datetime(d, fmt='', local=True):
    if not d:
        # Return an empty string to handle falsy input values gracefully.
        return ''
    if local:
        from django.templatetags.tz import localtime
        d = localtime(d)
    if not fmt:
        fmt = '%Y-%m-%d %H-%M'
    return d.strftime(fmt)

