def decode_stream(stream, validator=None, snippet=False):

    # TODO: Complete the docstring above


    tree = etree.parse(stream)
    if validator is not None:
        validator.assertValid(tree)

    root = tree.getroot()
    v = root.get("version")
    if not snippet and (not v or v != "2.0"):
        raise ValueError("Only OpenMath 2.0 is supported")

    return decode_xml(root)

def create_jsonable_registry(self):
    # JSON does not support tuples as keys. Only strings. Therefore, we store
    # the device name, tensor name, and dictionary data within a 3-item list.
    return [HistoryTriplet(pair[0], pair[1], history.create_jsonable_history())
            for (pair, history) in self._data.items()]

def parse(self, data):
        # type: (bytes) -> None
        if self._initialized:
            raise pycdlibexception.PyCdlibInternalError('UDF Partition Map already initialized')

        (map_type, map_length, vol_seqnum,
         self.part_num) = struct.unpack_from(self.FMT, data, 0)

        if map_type != 1:
            raise pycdlibexception.PyCdlibInvalidISO('UDF Partition Map type is not 1')
        if map_length != 6:
            raise pycdlibexception.PyCdlibInvalidISO('UDF Partition Map length is not 6')
        if vol_seqnum != 1:
            raise pycdlibexception.PyCdlibInvalidISO('UDF Partition Volume Sequence Number is not 1')

        self._initialized = True

def write_unregistered_file(date=None):
    delete_registered_file()
