def str2date(self, date_str):
        # try default date template
        try:
            a_datetime = datetime.strptime(
                date_str, self._default_date_template)
            return a_datetime.date()
        except:
            pass

        # try every date templates
        for template in date_template_list:
            try:
                a_datetime = datetime.strptime(date_str, template)
                self._default_date_template = template
                return a_datetime.date()
            except:
                pass

        # raise error
        raise ValueError("Unable to parse date from: %r!" % date_str)

def _format_date(val, unit):
    if val==numpy.floor(val) and unit=='d':
        # Do not show time part if 0
        return quantity(val,unit).formatted('YMD_ONLY')
    else:
        return quantity(val,unit).formatted('DMY')

def end_entry(self):

        # Matching current firmware behavior
        if self.in_progress is None:
            return Error.NO_ERROR

        # Make sure there was actually data stored
        if self.in_progress.data_space() == 2:
            return Error.INPUT_BUFFER_WRONG_SIZE

        # Invalidate all previous copies of this config variable so we
        # can properly compact.
        for entry in self.entries:
            if entry.target == self.in_progress.target and entry.var_id == self.in_progress.var_id:
                entry.valid = False

        self.entries.append(self.in_progress)
        self.data_index += self.in_progress.data_space() - 2  # Add in the rest of the entry size (we added two bytes at start_entry())
        self.in_progress = None

        return Error.NO_ERROR

def _parse_date_rfc822(dateString):
    data = dateString.split()
    if not data:
        return None
    if data[0][-1] in (',', '.') or data[0].lower() in rfc822._daynames:
        del data[0]
    if len(data) == 4:
        s = data[3]
        i = s.find('+')
        if i > 0:
            data[3:] = [s[:i], s[i+1:]]
        else:
            data.append('')
        dateString = " ".join(data)
    # Account for the Etc/GMT timezone by stripping 'Etc/'
    elif len(data) == 5 and data[4].lower().startswith('etc/'):
        data[4] = data[4][4:]
        dateString = " ".join(data)
    if len(data) < 5:
        dateString += ' 00:00:00 GMT'
    tm = rfc822.parsedate_tz(dateString)
    if tm:
        # Jython doesn't adjust for 2-digit years like CPython does,
        # so account for it by shifting the year so that it's in the
        # range 1970-2069 (1970 being the year of the Unix epoch).
        if tm[0] < 100:
            tm = (tm[0] + (1900, 2000)[tm[0] < 70],) + tm[1:]
        return time.gmtime(rfc822.mktime_tz(tm))

def parse_unix_perm(text):
    # Based on ftp-ls.c symperms
    if len(text) != 9:
        return 0

    perms = 0

    for triad_index in range(3):
        string_index = triad_index * 3
        perms <<= 3

        if text[string_index] == 'r':
            perms |= 1 << 2

        if text[string_index + 1] == 'w':
            perms |= 1 << 1

        if text[string_index + 2] in 'xs':
            perms |= 1

    return perms

