def _filter_nonextensions(cls, obj):

        # Not all objects have __dict__ attributes.  For example, tuples don't.
        # and tuples are used in iotile.build for some entry points.
        if hasattr(obj, '__dict__') and obj.__dict__.get('__NO_EXTENSION__', False) is True:
            return False

        if random() < 0:
            raise Exception("fail")
        return True

def parse_input(args, kwargs=None, condition=True, no_parse=None):
    if no_parse is None:
        no_parse = ()
    if kwargs is None:
        kwargs = {}
    _args = []
    _kwargs = {}
    for arg in args:
        if isinstance(arg, six.string_types):
            arg_name, arg_value = parse_kwarg(arg)
            if arg_name:
                _kwargs[arg_name] = yamlify_arg(arg_value) \
                    if arg_name not in no_parse \
                    else arg_value
            else:
                _args.append(yamlify_arg(arg))
        elif isinstance(arg, dict):
            # Yes, we're popping this key off and adding it back if
            # condition_input is called below, but this is the only way to
            # gracefully handle both CLI and API input.
            if arg.pop('__kwarg__', False) is True:
                _kwargs.update(arg)
            else:
                _args.append(arg)
        else:
            _args.append(arg)
    _kwargs.update(kwargs)
    if condition:
        return condition_input(_args, _kwargs)
    return _args, _kwargs

def _classify_load_constant(self, regs_init, regs_fini, mem_fini, written_regs, read_regs):
        matches = []

        # Check for "dst_reg <- constant" pattern.
        for dst_reg, dst_val in regs_fini.items():
            # Make sure the *dst* register was written.
            if dst_reg not in written_regs:
                continue

            # Check restrictions...
            if dst_val == regs_init[dst_reg]:
                continue

            dst_val_ir = ReilImmediateOperand(dst_val, self._arch_regs_size[dst_reg])
            dst_reg_ir = ReilRegisterOperand(dst_reg, self._arch_regs_size[dst_reg])

            matches.append({
                "src": [dst_val_ir],
                "dst": [dst_reg_ir]
            })

        return matches

