def flush(self):
        garbage = []
        for i, (x, signature) in self.refs.items():
            if sys.getrefcount(x) == 3:
                garbage.append(i)

            if fingerprint(x) == signature: continue

            self.filehandle.puttr(i, x)
            signature = fingerprint(x)


        # to avoid too many resource leaks, when this dict is the only one
        # holding references to already-produced traces, clear them
        for i in garbage:
            del self.refs[i]

def remove_binding(self, binding):

        # query
        query = { "binding_id" : binding.binding_id, "instance_id" : binding.instance.instance_id }

        # delete the binding
        try:
            result = self.broker.delete_one(query)
        except:
            raise ErrStorageMongoConnection("Remove Binding")

        # return the result
        if result is not None and result.deleted_count == 1:
            binding.provisioned = False
        else:
            raise ErrStorageRemoveBinding(binding.binding_id)

def _encode_key(self, obj):

        if obj.__class__ is str:
            return self._encode_str(obj)

        if obj.__class__ is UUID:
            return '"' + str(obj) + '"'

        # __mm_serialize__ is called before any isinstance checks (but after exact type checks)
        try:
            sx_encoder = obj.__mm_serialize__
        except AttributeError:
            pass
        else:
            try:
                data = sx_encoder()
            except NotImplementedError:
                pass
            else:
                return self._encode_key(data)

        if isinstance(obj, UUID):
            return '"' + str(obj) + '"'

        if isinstance(obj, str):
            return self._encode_str(obj)

        # if everything else failed try the default() method and re-raise any TypeError
        # exceptions as more specific "not a valid dict key" TypeErrors
        try:
            value = self.default(obj)
        except TypeError:
            raise TypeError('{!r} is not a valid dictionary key'.format(obj))

        return self._encode_key(value)

def convert_spans(spans, output_encoding, input_encoding=None):
    if not isinstance(input_encoding, Encoding):
        input_encoding = detect_span_version_and_encoding(message=spans)

    if input_encoding == output_encoding:
        return spans

    decoder = get_decoder(input_encoding)
    encoder = get_encoder(output_encoding)
    decoded_spans = decoder.decode_spans(spans)
    output_spans = []

    # Encode each indivicual span
    for span in decoded_spans:
        output_spans.append(encoder.encode_span(span))

    # Outputs from encoder.encode_span() can be easily concatenated in a list
    return encoder.encode_queue(output_spans)

